// Modern Task — pooled, awaitable, returns a value
int result = await Task.Run(() => 42);

// Task<T> composes naturally with async/await and error handling
async Task<int> ComputeAsync()
{
    try
    {
        return await Task.Run(() => 42);
    }
    catch (Exception ex)
    {
        // exceptions thrown inside Task.Run are captured and rethrown here
        throw new InvalidOperationException("Compute failed", ex);
    }
}

public async Task<string> GetOrderSummaryAsync(int id)
{
    Console.WriteLine("Before await");
    Order order = await _db.Orders.FindAsync(id); // <- THREAD RELEASED HERE
    Console.WriteLine("After await");              // resumes when the DB responds
    return $"Order {order.Id}";
}

// Sequential awaits: ~3s total (1s + 2s), one after another
var user = await GetUserAsync();     // 1s
var orders = await GetOrdersAsync(); // 2s

// Parallel awaits: ~2s total, both start immediately
Task<User> u = GetUserAsync();
Task<List<Order>> o = GetOrdersAsync();
await Task.WhenAll(u, o);

// ASP.NET Core injects it automatically — fires when the client disconnects
[HttpGet]
public async Task<IActionResult> GetOrders(CancellationToken cancellationToken)
{
    var orders = await _db.Orders.ToListAsync(cancellationToken);
    return Ok(orders);
}

