// In your own loop — cooperative checking, passed down the chain
public async Task ProcessBatchAsync(List<Order> orders, CancellationToken ct)
{
    foreach (var order in orders)
    {
        ct.ThrowIfCancellationRequested(); // stop between items
        await ProcessAsync(order, ct);      // pass it DOWN the chain
    }
}

