// IQueryable — becomes SQL; only 10 rows leave the DB
IQueryable<Order> q = db.Orders.Where(o => o.Amount > 1000);
var top = q.OrderByDescending(o => o.Amount).Take(10).ToList();
// SELECT TOP 10 ... WHERE Amount > 1000 ORDER BY Amount DESC

// IEnumerable — pulls EVERYTHING, then filters in app memory
IEnumerable<Order> e = db.Orders.AsEnumerable(); // 1M rows into RAM!
var top2 = e.Where(o => o.Amount > 1000).Take(10);

// IAsyncEnumerable — async streaming, one item at a time
public async IAsyncEnumerable<Order> StreamOrdersAsync(
    [EnumeratorCancellation] CancellationToken ct = default)
{
    await foreach (var order in _db.Orders.AsAsyncEnumerable().WithCancellation(ct))
        yield return order;
}

await foreach (var order in StreamOrdersAsync(ct))
    Process(order);

// Filtering / projection
products.Where(p => p.Price > 100);
products.Select(p => p.Name);
products.SelectMany(p => p.Tags); // flatten nested collections

// Ordering / paging
products.OrderBy(p => p.Name).ThenByDescending(p => p.Price);
products.Skip(20).Take(10);

// Aggregation
products.Count(); products.Sum(p => p.Price); products.Max(p => p.Price); products.Average(p => p.Price);

// Grouping / joining
products.GroupBy(p => p.CategoryId)
    .Select(g => new { g.Key, Total = g.Sum(p => p.Price) });
products.Join(categories, p => p.CategoryId, c => c.Id, (p, c) => new { p.Name, c.Title });

// Existence
products.Any(p => p.Price > 1000);
products.All(p => p.Price > 0);

// First/Single family
db.Users.SingleOrDefault(u => u.Email == email);              // unique column -> Single
db.Orders.OrderByDescending(o => o.Date).FirstOrDefault();    // newest -> First

// De-duplication
numbers.Distinct();
products.DistinctBy(p => p.CategoryId);        // .NET 6+
employees.GroupBy(e => e.Email).Select(g => g.First());
employees.GroupBy(e => e.Email).Where(g => g.Count() > 1)
